q:
次のプロバイダ設定があるとき、us-west-2 リージョンに S3 バケットを作成する resource ブロックの書き方として正しいものはどれか。

provider "aws" {
  region = "ap-northeast-1"
}

provider "aws" {
  alias  = "west"
  region = "us-west-2"
}

choices:
resource "aws_s3_bucket" "logs" {
  providers = { aws = aws.west }
  bucket    = "example-logs-west"
}

resource "aws_s3_bucket" "logs" {
  provider = aws.west
  bucket   = "example-logs-west"
}

resource "aws_s3_bucket" "logs" {
  region = "west"
  bucket = "example-logs-west"
}

resource "aws_s3_bucket" "logs" {
  alias  = aws.west
  bucket = "example-logs-west"
}

q:
次の構成で作成される、ユーザー alice に対応するリソースのアドレスはどれか。

variable "users" {
  type    = set(string)
  default = ["alice", "bob"]
}

resource "aws_iam_user" "this" {
  for_each = var.users
  name     = each.key
}

choices:
validation {
  condition = var.env in ["dev", "stg", "prod"]
}

lifecycle {
  prevent_destroy = var.env != "prod"
}

validation {
  condition     = contains(["dev", "stg", "prod"], var.env)
  error_message = "env は dev / stg / prod のいずれかを指定してください。"
}

precondition {
  condition     = contains(["dev", "stg", "prod"], var.env)
  error_message = "invalid env"
}

